      "operation": "create",
      "oldText": "",
      "newText": "<RadzenDataGrid T="BenchmarkResult" Data="@benchmarkResults">
    <Columns>
        <RadzenGridColumn T="BenchmarkResult" Field="Model" Title="Model" />
        <RadzenGridColumn T="BenchmarkResult" Field="Score" Title="Score" />
        <RadzenGridColumn T="BenchmarkResult" Field="ElapsedSeconds" Title="Elapsed Seconds" />
        <RadzenGridColumn T="BenchmarkResult" Field="Status" Title="Status" />
    </Columns>
</RadzenDataGrid>

@code {
    private List<BenchmarkResult> benchmarkResults = new List<BenchmarkResult>
    {
        new BenchmarkResult { Model = "Model1", Score = 95, ElapsedSeconds = 2.3, Status = "Passed" },
        new BenchmarkResult { Model = "Model2", Score = 88, ElapsedSeconds = 1.9, Status = "Failed" }
    };
}

public class BenchmarkResult
{
    public string Model { get; set; }
    public int Score { get; set; }
    public double ElapsedSeconds { get; set; }
    public string Status { get; set; }
}",
